#!/usr/bin/env bash
set -euo pipefail
ROUND="${1:?round}" CHECKPOINT="${2:?checkpoint}" OUT="${3:?output}"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"; PROJECT_DIR="$(cd "$SCRIPT_DIR/../.." && pwd)"; PYTHON_BIN="${SUCC_PYTHON_BIN:-/home/bdong/.venvs/molscribe_overlay/bin/python}"; SEED=7
P6="$PROJECT_DIR/outputs/p6_unified_transition_policy_v1/seed_${SEED}"; DIRECT="$PROJECT_DIR/outputs/direct_smiles_denovo_2p7p_v2_mixed_condition"; JOINT="$PROJECT_DIR/outputs/unified_smiles_generator_joint_v2"; P817="$PROJECT_DIR/outputs/p8_1_7_source_clamped_policy/r1/seed_${SEED}"; BASE="$PROJECT_DIR/outputs/p8_1_4_full_smiles_multitask_r1/seed_${SEED}/policy/unified_smiles_generator.pt"; P1="$PROJECT_DIR/outputs/direct_smiles_denovo_2p7p_v2_group_rl_v1/direct_smiles_model_group_rl/direct_smiles_generator_rl.pt"
mkdir -p "$OUT/eval/denovo/raw" "$OUT/eval/edit/raw"; export P817_SOURCE_CLAMP_SCALE=1.0
sample(){ local mode="$1" csv="$2" feat="$3" seed="$4"; "$PYTHON_BIN" "$SCRIPT_DIR/source_curriculum_entrypoint.py" sample --checkpoint "$CHECKPOINT" --eval-csv "$csv" --eval-condition-features-dir "$feat" --condition-layout unified --output-dir "$OUT/eval/$mode/raw" --prediction-csv "$OUT/eval/$mode/selected.csv" --candidate-output-csv "$OUT/eval/$mode/candidates.csv" --method "p8_1_10_${ROUND}" --decoding-mode sample --num-samples 20 --top-k-candidates 20 --max-candidates 20 --disable-finalizer --smiles-grammar-constraint --max-new-tokens 120 --temperature .8 --top-k 32 --top-p .95 --parallel-samples 10 --max-parallel-sequences 256 --seed "$seed" --device auto; }
sample denovo "$P6/data/denovo_hard_gate.csv" "$DIRECT/eval_condition_features_hf_vlm" 1817
sample edit "$P6/data/edit_table1_gate.csv" "$JOINT/feature_variants/validation_condition_features_hf_vlm" 2817
"$PYTHON_BIN" "$PROJECT_DIR/experiments/p8_1_7_source_clamped_policy/normalize_denovo_candidates.py" --input "$OUT/eval/denovo/candidates.csv" --output "$OUT/eval/denovo/candidates_normalized.csv"
"$PYTHON_BIN" "$PROJECT_DIR/experiments/p6_unified_molecular_transition_policy/evaluate_p6_denovo_gate.py" --eval-csv "$P6/data/denovo_hard_gate.csv" --candidates-csv "$OUT/eval/denovo/candidates_normalized.csv" --output-json "$OUT/eval/denovo/metrics.json" --output-md "$OUT/eval/denovo/report.md" --budgets 1,8,20
for k in 1 8 20;do "$PYTHON_BIN" "$PROJECT_DIR/scripts/evaluate_moledit_table1_anyk.py" --reference "$P6/data/edit_table1_gate.csv" --candidates "$OUT/eval/edit/candidates.csv" --output-dir "$OUT/eval/edit/any$k" --candidate-limit "$k" --model-name "p8_1_10_${ROUND}_any$k" --task-filter table1 --missing-oracle-policy fail;done
"$PYTHON_BIN" "$PROJECT_DIR/scripts/evaluate_moledit_table1_anyk.py" --reference "$P6/data/edit_table1_gate.csv" --candidates "$OUT/eval/edit/candidates.csv" --output-dir "$OUT/eval/edit/candidate20" --candidate-limit 20 --aggregation candidate --model-name "p8_1_10_${ROUND}_candidate20" --task-filter table1 --missing-oracle-policy fail
"$PYTHON_BIN" "$SCRIPT_DIR/audit_policy.py" --p1 "$P1" --base "$BASE" --checkpoint "$CHECKPOINT" --denovo "$OUT/eval/denovo/candidates_normalized.csv" --denovo-reference "$P817/eval/denovo/candidates_normalized.csv" --edit "$OUT/eval/edit/candidates.csv" --round "$ROUND" --output "$OUT/final_audit.json"
touch "$OUT/COMPLETE"
